@r2 syntax.relation marker="to" from=$c1 to=$n4
@n4 syntax.nominal dependent="the" dependent="top" head="twenty"

sop:
@n1 syntax.nominal dependent="The" dependent="next" head="thing"
@c1 syntax.clause form=declarative verb="is" subject=$n1
@r1 syntax.relation marker="to" from=$c1 to=$c2
@c2 syntax.clause form=nonfinite verb="bump" modifier="up" complement=$n2
@n2 syntax.nominal dependent="the" head="chart"
@r2 syntax.relation marker="to" from=$c2 to=$n3
@n3 syntax.nominal dependent="the" dependent="top" head="ten"

alt:
@n1 syntax.nominal dependent="The" dependent="next" head="thing"
@c1 syntax.clause form=declarative verb="is" subject=$n1
@r1 syntax.relation marker="to" from=$c1 to=$c2
@c2 syntax.clause form=nonfinite verb="bump" modifier="ten" complement=$n2
@n2 syntax.nominal dependent="the" head="chart"
@r2 syntax.relation marker="up to" from=$c2 to=$n3
@n3 syntax.nominal dependent="the" head="top"
